package ru.kstolu.app;
import android.app.*;import android.content.*;import android.os.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.view.*;import android.widget.*;import org.json.*;import java.util.Locale;
/** A self-contained pager inside the recipe, not an Activity or a second screen. */
final class InlineCooking extends LinearLayout {
 private final Activity host;private final JSONObject item,recipe;private final JSONArray steps;private final SharedPreferences store;private final String key;private final Handler handler=new Handler(Looper.getMainLooper());private CookingState state;private TextView clock;private Button play;private boolean active=false,moving=false;private float downX,downY;
 private static final int INK=0xff253127,OLIVE=0xff4c6441,MUTED=0xff626d61,SOFT=0xffeaf0e4;
 InlineCooking(Activity context,JSONObject snapshot)throws Exception{super(context);host=context;item=new JSONObject(snapshot.toString());recipe=item.getJSONObject("recipe");steps=recipe.getJSONArray("steps");if(steps.length()==0)throw new IllegalArgumentException();store=host.getSharedPreferences("cooking",0);key="state:"+Library.id(recipe);state=CookingState.restore(new JSONObject(store.getString(key,"{}")),boot());state.index=Math.min(state.index,steps.length());setOrientation(VERTICAL);setPadding(dp(18),dp(18),dp(18),dp(18));setBackground(bg(Color.WHITE));render();}
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private int boot(){return android.provider.Settings.Global.getInt(host.getContentResolver(),android.provider.Settings.Global.BOOT_COUNT,0);}
 private GradientDrawable bg(int c){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(18));g.setStroke(dp(1),0xffdde4d5);return g;}
 private TextView text(String s,int size,boolean bold){TextView t=new TextView(host);t.setText(s);t.setTextColor(INK);t.setTextSize(size);t.setLineSpacing(dp(4),1);if(bold)t.setTypeface(null,Typeface.BOLD);LayoutParams p=new LayoutParams(-1,-2);p.setMargins(0,dp(6),0,dp(10));addView(t,p);return t;}
 private Button button(String s,Runnable action,boolean primary){Button b=new Button(host);b.setText(s);b.setTextSize(15);b.setAllCaps(false);b.setTextColor(primary?Color.WHITE:OLIVE);b.setTypeface(null,Typeface.BOLD);b.setBackground(bg(primary?OLIVE:SOFT));b.setPadding(dp(8),dp(10),dp(8),dp(10));b.setMinHeight(dp(48));b.setOnClickListener(v->action.run());return b;}
 private void persist(){try{state.remaining=state.left(SystemClock.elapsedRealtime());store.edit().putString(key,state.json().toString()).putString("item",item.toString()).apply();}catch(Exception ignored){}}
 void resumeTimer(){if(active)return;active=true;if(state.expire(SystemClock.elapsedRealtime())){persist();render();}handler.post(tick);}
 void suspendTimer(){active=false;handler.removeCallbacks(tick);persist();}
 @Override protected void onAttachedToWindow(){super.onAttachedToWindow();resumeTimer();}
 @Override protected void onDetachedFromWindow(){suspendTimer();super.onDetachedFromWindow();}
 private final Runnable tick=new Runnable(){public void run(){if(!active)return;if(state.expire(SystemClock.elapsedRealtime())){persist();render();announceForAccessibility("Таймер завершён. Проверьте готовность. Следующий шаг.");}updateClock();handler.postDelayed(this,500);}};
 private void render(){removeAllViews();clock=null;play=null;
  if(state.index>=steps.length()){text("Вы приготовили блюдо!",23,true);text("Как получилось? Оценка останется в сохранённом.",15,false).setTextColor(MUTED);RatingBar stars=new RatingBar(host);stars.setNumStars(5);stars.setStepSize(1);stars.setRating(Library.rating(host,recipe));addView(stars,new LayoutParams(-2,-2));Button save=button("Сохранить оценку",()->{int n=Math.round(stars.getRating());if(n<1){Toast.makeText(host,"Выберите от 1 до 5 звёзд",Toast.LENGTH_SHORT).show();return;}try{Library.save(host,item);Library.rate(host,recipe,n);Toast.makeText(host,"Приятного аппетита! Оценка сохранена.",Toast.LENGTH_SHORT).show();}catch(Exception e){Toast.makeText(host,"Не удалось сохранить оценку.",Toast.LENGTH_SHORT).show();}},true);addView(save,new LayoutParams(-1,-2));Button again=button("Вернуться к шагам",()->move(-1),false);LayoutParams ap=new LayoutParams(-1,-2);ap.topMargin=dp(8);addView(again,ap);return;}
  TextView label=text("ШАГ "+(state.index+1)+" / "+steps.length(),12,true);label.setTextColor(OLIVE);label.setLetterSpacing(.1f);ProgressBar progress=new ProgressBar(host,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(steps.length());progress.setProgress(state.index+1);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(OLIVE));addView(progress,new LayoutParams(-1,dp(4)));
  JSONObject step=steps.optJSONObject(state.index);text(step.optString("title"),23,true);text(step.optString("body"),16,false);
  if(item.optInt("portions",recipe.optInt("servings",2))!=recipe.optInt("servings",2))text("Количества берите из ингредиентов выше. Время приготовления не умножается на число порций.",14,false).setTextColor(MUTED);
  long preset=step.optLong("timer_seconds",0);if(preset>0||state.remaining>0||state.running){LinearLayout row=new LinearLayout(host);row.setGravity(Gravity.CENTER_VERTICAL);row.setBackground(bg(SOFT));row.setPadding(dp(12),dp(8),dp(8),dp(8));clock=new TextView(host);clock.setTextSize(25);clock.setTypeface(Typeface.MONOSPACE,Typeface.BOLD);clock.setTextColor(OLIVE);row.addView(clock,new LayoutParams(0,dp(48),1));play=button("▷",()->{if(state.running)state.pause(SystemClock.elapsedRealtime());else state.start(state.remaining>0?(state.remaining+999)/1000:preset,SystemClock.elapsedRealtime(),boot());persist();updateClock();},true);row.addView(play,new LayoutParams(dp(48),dp(48)));Button edit=button("⋯",this::editTimer,false);edit.setContentDescription("Изменить таймер");LayoutParams ep=new LayoutParams(dp(48),dp(48));ep.leftMargin=dp(6);row.addView(edit,ep);addView(row,new LayoutParams(-1,-2));text(step.optString("timer_hint","Запустите таймер, когда начнётся этап."),14,false).setTextColor(MUTED);text("По окончании откроется следующий шаг. Проверьте готовность еды.",14,false).setTextColor(MUTED);}else{Button add=button("＋ Таймер",this::editTimer,false);addView(add,new LayoutParams(-1,-2));}
  LinearLayout nav=new LinearLayout(host);Button previous=button("‹ Назад",()->move(-1),false);previous.setEnabled(state.index>0);nav.addView(previous,new LayoutParams(0,-2,1));Button next=button(state.index==steps.length()-1?"Готово ✓":"Далее ›",()->move(1),true);LayoutParams np=new LayoutParams(0,-2,1);np.leftMargin=dp(8);nav.addView(next,np);LayoutParams n=new LayoutParams(-1,-2);n.topMargin=dp(16);addView(nav,n);updateClock();
 }
 private void updateClock(){if(clock==null||state.index>=steps.length())return;long sec=state.running||state.remaining>0?(state.left(SystemClock.elapsedRealtime())+999)/1000:steps.optJSONObject(state.index).optLong("timer_seconds",0);clock.setText(String.format(Locale.ROOT,"%02d:%02d",sec/60,sec%60));play.setText(state.running?"Ⅱ":"▷");play.setContentDescription(state.running?"Пауза таймера":"Запустить таймер");}
 private void editTimer(){state.pause(SystemClock.elapsedRealtime());persist();EditText minutes=new EditText(host);minutes.setHint("Минуты, например 8,5");minutes.setInputType(8194);minutes.setKeyListener(android.text.method.DigitsKeyListener.getInstance("0123456789.,"));long sec=state.remaining>0?(state.remaining+999)/1000:steps.optJSONObject(state.index).optLong("timer_seconds",0);if(sec>0)minutes.setText(String.format(Locale.ROOT,"%.2f",sec/60d));AlertDialog d=new AlertDialog.Builder(host).setTitle("Таймер в минутах").setMessage("Запускается только по нажатию. В фоне время сохраняется, звук при закрытом приложении не гарантируется.").setView(minutes).setNegativeButton("Отмена",null).setNeutralButton("Сбросить",(v,w)->{state.remaining=0;state.deadline=0;persist();render();}).setPositiveButton("Установить",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{double value=Double.parseDouble(minutes.getText().toString().trim().replace(',','.'));if(!Double.isFinite(value)||value<1d/60||value>360)throw new Exception();state.remaining=Math.round(value*60)*1000;state.deadline=0;persist();render();d.dismiss();}catch(Exception e){minutes.setError("От 1 секунды до 360 минут");}}));d.show();}
 void move(int delta){if(moving)return;int target=Math.max(0,Math.min(steps.length(),state.index+delta));if(target==state.index)return;Runnable go=()->{state.pause(SystemClock.elapsedRealtime());state.remaining=0;state.index=target;persist();if(android.animation.ValueAnimator.areAnimatorsEnabled()){moving=true;animate().alpha(.25f).translationX(dp(delta>0?-12:12)).setDuration(100).withEndAction(()->{render();setTranslationX(dp(delta>0?12:-12));animate().alpha(1).translationX(0).setDuration(160).withEndAction(()->moving=false).start();}).start();}else render();};if(state.running)new AlertDialog.Builder(host).setTitle("Перейти к следующему шагу?").setMessage("Таймер текущего шага будет остановлен.").setNegativeButton("Остаться",null).setPositiveButton("Перейти",(d,w)->go.run()).show();else go.run();}
 @Override public boolean dispatchTouchEvent(MotionEvent event){if(event.getActionMasked()==MotionEvent.ACTION_DOWN){downX=event.getX();downY=event.getY();}if(event.getActionMasked()==MotionEvent.ACTION_UP){float dx=event.getX()-downX,dy=event.getY()-downY;if(Math.abs(dx)>dp(75)&&Math.abs(dx)>Math.abs(dy)*2){MotionEvent cancel=MotionEvent.obtain(event);cancel.setAction(MotionEvent.ACTION_CANCEL);super.dispatchTouchEvent(cancel);cancel.recycle();move(dx<0?1:-1);return true;}}return super.dispatchTouchEvent(event);}
}
